-- Only activate gear after checking that the entire dataset was packaged.
-- A missing module must never reveal the obsolete unverified rankings.
if not BiSCompanionForever or type(BiSCompanionBisData) ~= 'table' then return end
local total, valid = 0, 0
for _, mapping in ipairs(BiSCompanionClassSpecMapping or {}) do
    total = total + 1
    local items = lists[mapping.specKey]
    if type(items) ~= 'table' or #items < 12 then return end
    local seen = {}
    for _, item in ipairs(items) do
        if not tonumber(item.id) or not item.slot or seen[item.slot] then return end
        seen[item.slot] = true
    end
    valid = valid + 1
end
if total ~= 28 or valid ~= total then return end
for spec, items in pairs(lists) do BiSCompanionBisData[spec] = items end
BiSCompanionForeverGearReady = true
